// URLPreview represents the extracted preview data from a webpage.
type URLPreview struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// FetchURLPreview handles POST requests to /preview.
// It expects a JSON body with a "url" field, fetches the URL with a 3-second timeout,
// parses the HTML, and returns the page title and meta description.
func FetchURLPreview(ctx echo.Context) error {
	// Parse request body
	var req struct {
		URL string `json:"url"`
	}
	if err := ctx.Bind(&req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{
			"error": "Invalid request body",
		})
	}

	if req.URL == "" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{
			"error": "URL is required",
		})
	}

	// Create context with 3-second timeout
	clientCtx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()

	// Create HTTP request
	httpReq, err := http.NewRequestWithContext(clientCtx, http.MethodGet, req.URL, nil)
	if err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{
			"error": "Invalid URL",
		})
	}

	// Perform the request
	client := &http.Client{}
	resp, err := client.Do(httpReq)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{
			"error": "Failed to fetch URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Read response body
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{
			"error": "Failed to read response body",
		})
	}

	// Parse HTML and extract title and description
	preview := parseHTML(string(body))

	return ctx.JSON(http.StatusOK, preview)
}

// parseHTML parses the HTML content and extracts the title and meta description.
func parseHTML(htmlContent string) URLPreview {
	preview := URLPreview{}
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return preview
	}

	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" && n.FirstChild != nil {
				preview.Title = n.FirstChild.Data
			}
			if n.Data == "meta" {
				var name, content string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						name = attr.Val
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" && preview.Description == "" {
					preview.Description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(doc)

	return preview
}

