)

// Request body
type PreviewRequest struct {
	URL string `json:"url"`
}

// Response body
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
}

// isPrivateIP checks if an IP address is private, loopback, link-local, or otherwise internal
func isPrivateIP(ip net.IP) bool {
	if ip == nil {
		return true
	}
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
		return true
	}
	// Check for IPv4-mapped IPv6 addresses (e.g., ::ffff:10.0.0.1)
	if ip4 := ip.To4(); ip4 != nil {
		return ip4.IsLoopback() || ip4.IsPrivate() || ip4.IsLinkLocalUnicast() || ip4.IsLinkLocalMulticast() || ip4.IsUnspecified()
	}
	return false
}

// safeDialContext returns a DialContext function that validates the resolved IP
func safeDialContext() func(ctx context.Context, network, addr string) (net.Conn, error) {
	return func(ctx context.Context, network, addr string) (net.Conn, error) {
		// Parse host and port from addr
		host, port, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, fmt.Errorf("invalid address: %w", err)
		}

		// Resolve the host to IP addresses
		ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
		if err != nil {
			return nil, fmt.Errorf("DNS resolution failed: %w", err)
		}

		// Check all resolved IPs
		for _, ipAddr := range ips {
			if isPrivateIP(ipAddr.IP) {
				return nil, fmt.Errorf("blocked: request to internal/private IP address")
			}
		}

		// Use the first resolved IP to avoid DNS rebinding
		if len(ips) == 0 {
			return nil, fmt.Errorf("no IP addresses resolved")
		}

		// Create a dialer that connects to the validated IP
		dialer := &net.Dialer{}
		return dialer.DialContext(ctx, network, net.JoinHostPort(ips[0].IP.String(), port))
	}
}

// safeTransport creates an HTTP transport with SSRF protection
func safeTransport() *http.Transport {
	return &http.Transport{
		DialContext: safeDialContext(),
		// Disable redirects to prevent redirect-based SSRF
		// We handle redirects manually to validate each redirect target
	}
}

// validateURL performs comprehensive SSRF checks on a URL
func validateURL(rawURL string) (*url.URL, error) {
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL format")
	}

	// Only allow HTTP/HTTPS schemes
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return nil, fmt.Errorf("only HTTP/HTTPS URLs are allowed")
	}

	// Reject empty hosts
	if parsedURL.Host == "" {
		return nil, fmt.Errorf("empty host not allowed")
	}

	// Parse host and port
	host := parsedURL.Hostname()

	// Check for decimal/octal/hex IP representations
	ip := net.ParseIP(host)
	if ip == nil {
		// Try to parse as decimal IP (e.g., http://2130706433/ for 127.0.0.1)
		// This is handled by DNS resolution in safeDialContext
	} else {
		if isPrivateIP(ip) {
			return nil, fmt.Errorf("internal/private IP addresses are not allowed")
		}
	}

	// Check for common DNS rebinding hosts
	lowerHost := strings.ToLower(host)
	dangerousHosts := []string{
		"localhost", "localtest.me", "127.0.0.1", "0.0.0.0",
		"[::1]", "::1",
	}
	for _, dh := range dangerousHosts {
