		}
		return isPrivateIP(ip4)
	}
	return false
}

// validateURL performs security checks on the URL to prevent SSRF.
func validateURL(rawURL string) error {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return fmt.Errorf("invalid URL: %w", err)
	}

	// Block dangerous protocols
	scheme := strings.ToLower(parsed.Scheme)
	if scheme != "http" && scheme != "https" {
		return fmt.Errorf("protocol not allowed: %s", scheme)
	}

	// Resolve host to IP addresses
	host := parsed.Hostname()
	if host == "" {
		return fmt.Errorf("empty host")
	}

	// Check for DNS rebinding via hostname tricks
	if strings.ToLower(host) == "localtest.me" {
