    clientCtx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
    defer cancel()

    // Create HTTP request with context
    httpReq, err := http.NewRequestWithContext(clientCtx, http.MethodGet, req.URL, nil)
    if err != nil {
